  float sparkleHash(float x) {
    return fract(sin(mod(x,3097.0)*34.371+2.17)*7451.37);
  }
  float starDistance(vec2 delta,float radius) {
    vec2 p=abs(delta)/vec2(radius,radius*1.18);
    return max(p.x,p.y)+2.4*min(p.x,p.y);
  }
  vec4 frontFlame() {
    vec2 pixel = vec2((uv0.x-0.5)*64.0,(0.5-uv0.y)*84.0+10.0);
    vec2 iconUV = vec2(pixel.x,-pixel.y)/48.0+0.5;
    float seed = floor(color.r*255.0+0.5);
    #if STILL
      float time = 0.0;
    #else
      float time = crestTime();
    #endif
    vec2 source=vec2(31.6+seed*0.17,4.3+seed*0.061);
    vec2 plumeUV=pixel*vec2(0.118,0.083)+source-vec2(0.0,time*0.94);
    float plume=cloud(plumeUV)*0.7+cloud(pixel*vec2(0.21,0.155)+source.yx+vec2(11.9,-time*1.67))*0.3;
    float upper=-13.0+28.0*plume;
    float veil=coverage(iconUV)*smoothstep(-24.0,-14.0,pixel.y)*(1.0-smoothstep(upper-4.0,upper+1.0,pixel.y));
    float alpha=veil*(0.22+0.27*plume);
    vec3 flame=flameSpectrum(pixel.x*0.082+time*1.122+plume*1.5);
    #if STILL
      float d=starDistance(pixel-vec2(11.0,12.0),6.0);
      float visibility=0.94;
    #else
      float cycle=time/1.4+sparkleHash(seed);
      float key=seed*7.0+floor(cycle)*11.0;
      float life=fract(cycle)*1.4/(0.88+sparkleHash(key+1.0)*0.22);
      vec2 spawn=(vec2(sparkleHash(key+2.0),sparkleHash(key+3.0))-0.5)*46.0;
      vec2 drift=vec2((sparkleHash(key+4.0)-0.5)*4.0,12.0+sparkleHash(key+5.0)*7.0);
