    float edge = length(max(q,vec2(0.0))) + min(max(q.x,q.y),0.0) - 9.0;
    float rim = exp(-abs(edge)*0.76);
    return vec4(mix(color.rgb,vec3(1.0),rim*0.45),rim*color.a);
  #elif FRONT_FLAME
    return frontFlame();
  #elif ICON_HALO
    vec2 uv = (uv0 - 0.5) * (58.0/48.0) + 0.5;
    #if FLAME_EDGE
      #if STILL
        float time = 0.0;
      #else
        float time = crestTime();
      #endif
      vec2 p = uv*vec2(8.0,3.6)+vec2(1.7,time*(8.0/5.6));
      float noise = cloud(p)*0.72+cloud(p*2.0+vec2(5.1,2.6))*0.28;
      float cloudMask = smoothstep(0.28,0.70,noise);
      float radius = pow(clamp(length(uv-0.5)*2.0,0.0,1.0),0.7);
      float reach = mix(3.5,8.0,mix(0.45,cloudMask,0.52+0.48*radius));
    #endif
    float halo = 0.0;
    for (int i=0; i<12; ++i) {
      float a = float(i) * 0.52359878;
      vec2 dir = vec2(cos(a),sin(a))/48.0;
      #if FLAME_EDGE
        halo += 0.45 * coverage(uv+dir*(reach*0.55));
        halo += coverage(uv+dir*reach+vec2(0.0,cloudMask*0.022));
      #else
        halo += coverage(uv+dir*2.5) + coverage(uv+dir*4.8)*0.82;
      #endif
    }
    #if FLAME_EDGE
      vec2 cellCorner = max(abs((uv0-0.5)*58.0)-vec2(18.5),vec2(0.0));
      float cellMask = 1.0-smoothstep(8.0,9.0,length(cellCorner));
      halo = min(1.0,halo*0.64) * (1.0-coverage(uv)) * cellMask;
    #else
      halo = min(1.0,halo*0.34) * (1.0-coverage(uv));
    #endif
    #if FLAME_EDGE
      vec3 ink = color.rgb;
    #else
      vec3 ink = mix(color.rgb,vec3(1.0),0.37);
    #endif
    #if GOLD
      float angle = atan(uv.y-0.5,uv.x-0.5+0.00001);
      #if !STILL
        angle -= crestTime() * 0.57;
      #endif
      ink = flameSpectrum(angle*2.0);
    #endif
    return vec4(ink,halo*color.a);
  #else
    vec4 icon = CCSampleWithAlphaSeparated(cc_spriteTexture,uv0);
    float axis = uv0.x + 0.34*uv0.y;
    #if STILL
      float center = 0.68;
    #else
      float center = -0.20 + mod(crestTime()+color.r*5.6,5.6)*0.69;
    #endif
    float band = 1.0-smoothstep(0.061,0.074,abs(axis-center));
    #if GOLD
      vec3 metal = vec3(1.0,0.78,0.33);
    #else
      vec3 metal = vec3(0.88,0.94,1.0);
    #endif
    icon.rgb = mix(icon.rgb,metal,band*0.82);
    return vec4(icon.rgb,icon.a*color.a);
  #endif
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

